'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Returns the first index of an element in a single-precision floating-point strided array which is less than or equal to a specified search element.
*
* ## Notes
*
* -   If unable to find an element which is less than or equal to the search element, the function returns `-1`.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {number} searchElement - search element
* @param {Float32Array} x - input array
* @param {integer} strideX - stride length
* @returns {integer} index
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 2.0, 3.0, 1.0, 4.0 ] );
*
* var idx = sindexOfLessThanEqual( x.length, 1.0, x, 1 );
* // returns 2
*/
function sindexOfLessThanEqual( N, searchElement, x, strideX ) {
	return addon( N, searchElement, x, strideX );
}


// EXPORTS //

module.exports = sindexOfLessThanEqual;
